import {escapeHTML as esc,fa,dateLabel} from './core.mjs?v=3';
import {roles} from './policy.mjs?v=3';
import {uid} from './factory-model.mjs?v=3';

export function reviseMessage(message,text,actor,archive,contactId){
 if(message.self===false||message.deleted)throw new Error('فقط پیام خودتان قابل ویرایش است.');
 const value=String(text||'').trim();if(!value)throw new Error('متن پیام خالی است.');
 archive.push({id:uid('ARCH'),type:'message-edit',actor,contactId,date:new Date().toISOString(),original:structuredClone(message)});
 message.text=value;message.editedAt=new Date().toISOString();return message;
}
export function removeMessage(message,actor,archive,contactId){
 if(message.self===false||message.deleted)throw new Error('فقط پیام خودتان قابل حذف است.');
 archive.push({id:uid('ARCH'),type:'message-delete',actor,contactId,date:new Date().toISOString(),original:structuredClone(message)});
 const id=message.id;for(const key of Object.keys(message))delete message[key];Object.assign(message,{id,deleted:true,self:true,date:new Date().toISOString()});return message;
}
export function sourceExcerpt(list,ids){return list.filter(m=>ids.includes(m.id)&&!m.deleted).map(m=>m.text||({audio:'[پیام صوتی]',image:'[تصویر]',video:'[ویدئو]',file:'[فایل]',album:'[آلبوم]'}[m.kind]||'')).join('\n\n');}
export const archiveFor=(actor,archive)=>actor==='alireza'?archive:[];

export function messenger(c){
 const u={filter:'active',search:'',selected:[],reply:null,chosen:null,pending:null,recorder:null,stream:null,cancelVoice:false,busy:false};
 const state=()=>c.space();const contacts=()=>state().contacts||[];const threads=()=>state().messages;const current=()=>contacts().find(x=>x.id===c.contact());
 const action=(name,label,data='',cls='secondary')=>`<button type="button" class="${cls}" data-msg="${name}" ${data}>${label}</button>`;
 const photo=src=>`<button type="button" class="msg-photo" data-action="view-image" data-src="${esc(src)}"><img src="${esc(src)}" alt="عکس گفتگو"></button>`;
 const attachment=m=>m.kind==='image'?photo(m.src):m.kind==='album'?`<div class="msg-album">${m.attachments.map(attachment).join('')}</div>`:m.kind==='video'?`<video controls playsinline preload="metadata" src="${esc(m.src)}"></video>`:m.kind==='audio'?`<audio controls preload="metadata" src="${esc(m.src)}"></audio>`:m.kind==='file'?`<a href="${esc(m.src)}" download="${esc(m.fileName||m.text||'file')}">${c.icon('file','sm')}${esc(m.fileName||m.text||'فایل')}</a>`:'';
 function renderMessage(m){return `<div class="message ${m.self===false?'':'self'} ${u.selected.includes(m.id)?'msg-selected':''}" data-message-id="${esc(m.id)}">${m.deleted?'<p class="muted">این پیام حذف شده است.</p>':`${m.sender?`<small>${esc(m.sender)}</small>`:''}${m.forwarded?'<small>بازارسال‌شده</small>':''}${m.reply?`<div class="reply-preview">${esc(m.reply.text||m.reply)}</div>`:''}${attachment(m)}${m.text?`<p data-user-content>${esc(m.text)}</p>`:''}${m.source?`<small class="message-note">منبع: ${esc(m.source.label)}</small>`:''}${m.reminder?`<div class="message-note">${c.icon('clock','sm')}${esc(dateLabel(m.reminder,{day:'numeric',month:'long'}))} · ${esc(new Date(m.reminder).toLocaleTimeString('fa-IR',{hour:'2-digit',minute:'2-digit'}))} ${m.reminderState==='done'?'· انجام شد':m.reminderState==='cancelled'?'· لغو شد':''}</div>`:''}<div class="message-time">${m.pinned?'سنجاق‌شده · ':''}${m.editedAt?'ویرایش‌شده · ':''}${esc(m.time||'اکنون')} ${m.self===false?'':'· ذخیره در این دستگاه'}</div><button type="button" class="message-menu" data-msg="menu" data-id="${esc(m.id)}" aria-label="گزینه‌های پیام">${c.icon('more','sm')}</button>`}</div>`;}
 function renderContacts(){return contacts().filter(x=>u.filter==='archived'?x.archived:!x.archived).filter(x=>(x.name+' '+(threads()[x.id]||[]).filter(m=>!m.deleted).map(m=>m.text||'').join(' ')).includes(u.search)).sort((a,b)=>Number(!!b.pinned)-Number(!!a.pinned)).map(x=>{const last=(threads()[x.id]||[]).filter(m=>!m.deleted).at(-1);return `<button class="contact-row contact ${c.contact()===x.id?'is-active':''}" data-msg="open" data-contact="${x.id}">${c.avatar(x.initial||x.name)}<span class="contact-body"><b>${esc(x.name)}</b><small>${x.pinned?'سنجاق‌شده · ':''}${x.muted?'بی‌صدا · ':''}${esc(last?.text||x.role||'گفتگوی جدید')}</small></span><span>${x.group?c.icon('users','sm'):''}</span></button>`;}).join('')||'<p class="empty-state">گفتگویی پیدا نشد.</p>';}
 function render(){const x=current(),list=x?(threads()[x.id]||[]):[],q=u.search.trim();return `<div class="messenger ${x?'chat-open':''}"><aside class="contacts-panel conversation-list"><div class="contacts-head"><h1>مسنجر</h1>${action('new','گفتگوی جدید')}${action('group','گروه جدید')}</div><label class="searchbox">${c.icon('search','sm')}<input id="messenger-search" type="search" aria-label="جستجوی گفتگو و پیام" placeholder="جستجوی گفتگو و پیام" value="${esc(u.search)}"></label><div class="op-actions">${action('active','گفتگوها','',u.filter==='active'?'primary':'text-link')}${action('archived','بایگانی','',u.filter==='archived'?'primary':'text-link')}${action('self','برای خودم','','text-link')}</div><div id="messenger-contacts">${renderContacts()}</div><p class="sheet-body-note">اطلاعات نمونه همین مرورگر · ارسال بین حساب‌های واقعی بعد از اتصال سرویس</p></aside><section class="chat-panel chat">${!x?`<div class="chat-placeholder">${c.icon('send')}<h2>پیام‌ها و همکاری روزانه</h2><p>گفتگو، عکس، فیلم، فایل، ویس و یادداشت شخصی</p>${action('new','شروع گفتگو')}</div>`:`<div class="chat-head">${action('back',c.icon('back'),'aria-label="بازگشت به گفتگوها"','icon-btn chat-back')}${c.avatar(x.initial||x.name)}<button data-msg="info"><b>${esc(x.name)}</b><small>${esc(x.id==='self'?'فضای خصوصی این حساب':x.role||'گفتگوی نمونه')}</small></button><div class="chat-head-actions">${x.id==='self'?action('reminder',c.icon('clock'),'aria-label="یادآور جدید"','icon-btn'):action('call',c.icon('phone'),'aria-label="تماس"','icon-btn')}${action('chat-options',c.icon('more'),'aria-label="تنظیمات گفتگو"','icon-btn')}</div></div>${x.id==='self'?'<div class="self-intro">نوت‌ها، منابع ذخیره‌شده و یادآورهای خصوصی همین حساب</div>':''}<div class="chat-messages">${q?`<small>نتیجه جستجو: ${esc(q)}</small>`:''}${list.filter(m=>!q||m.text?.includes(q)).map(renderMessage).join('')||'<div class="empty-state">هنوز پیامی در این گفتگو نیست.</div>'}</div>${u.selected.length?`<div class="chat-tools">${fa(u.selected.length)} پیام انتخاب شد ${action('summary','گزیده قابل ویرایش')}${action('clear-selection','لغو')}</div>`:''}${u.reply?`<div class="chat-tools">پاسخ به: ${esc(u.reply.text||'رسانه')}${action('cancel-reply','لغو')}</div>`:''}<form class="chat-composer" id="messenger-form"><button type="button" class="icon-btn" data-msg="attach" aria-label="پیوست عکس فیلم ویس فایل">${c.icon('paperclip')}</button><button type="button" class="icon-btn" data-msg="camera" aria-label="دوربین">${c.icon('camera')}</button><textarea id="messenger-text" name="text" aria-label="متن پیام" placeholder="${x.id==='self'?'یادداشت برای خودم':'پیام'}" rows="1">${esc(c.draft(x.id)||'')}</textarea><button type="submit" class="icon-btn" aria-label="ارسال پیام">${c.icon('send')}</button><button type="button" class="icon-btn ${u.recorder?.state==='recording'?'recording':''}" data-msg="voice" aria-label="${u.recorder?.state==='recording'?'توقف ضبط و بازبینی':'ضبط ویس'}">${c.icon(u.recorder?.state==='recording'?'stop':'mic')}</button><input id="messenger-file" type="file" hidden multiple accept="image/*,video/*,audio/*,.pdf,.txt,.csv,.xlsx,.docx"><input id="messenger-camera" type="file" hidden accept="image/*" capture="environment"></form>${u.recorder?.state==='recording'?`<div class="chat-tools">در حال ضبط ${action('cancel-recording','لغو ضبط')}</div>`:''}`}</section></div>`;}
 function persist(){c.save();c.render(true);}
 function add(contactId,text,extra={}){if(!threads()[contactId])return;threads()[contactId].push({id:uid('MSG'),kind:'text',self:true,actor:c.actor(),date:new Date().toISOString(),time:new Date().toLocaleTimeString('fa-IR',{hour:'2-digit',minute:'2-digit'}),text,...(u.reply?{reply:{id:u.reply.id,text:u.reply.text||'رسانه'}}:{}),...extra});u.reply=null;c.setDraft(contactId,'');persist();}
 const chosen=()=>threads()[u.chosen?.contactId]?.find(m=>m.id===u.chosen.id);
 function menu(id){const m=(threads()[c.contact()]||[]).find(m=>m.id===id);if(!m||m.deleted)return;u.chosen={id,contactId:c.contact()};c.modal('گزینه‌های پیام',`<p data-user-content>${esc(m.text||'رسانه')}</p>${[['reply','پاسخ'],['forward','بازارسال'],['react','واکنش'],['note','ذخیره برای خودم'],['reminder','یادآور از این پیام'],['select','انتخاب برای گزیده'],['pin-message',m.pinned?'برداشتن سنجاق':'سنجاق پیام'],...(m.reminder?[['reminder-done','انجام شد'],['reminder-edit','ویرایش یادآور'],['reminder-snooze','تعویق یادآور'],['reminder-cancel','لغو یادآور']]:[]),...(m.self!==false?[['edit','ویرایش متن'],['delete','حذف پیام']]:[])].map(([a,l])=>action(a,l,'','list-link')).join('')}<div class="message-reactions">${Object.entries(m.reactions||{}).map(([k,v])=>`${esc(k)} ${fa(v.length)}`).join(' ')}</div>`);}
 function reminder(existing=null){const m=existing||chosen(),value=m?.reminder?new Date(new Date(m.reminder)-new Date(m.reminder).getTimezoneOffset()*60000).toISOString().slice(0,16):'';c.modal('یادآور شخصی',`<form id="messenger-reminder" data-edit="${existing?.id||''}"><div class="field"><label>یادداشت<textarea name="text" aria-label="متن پیام" required>${esc(m?.text||'')}</textarea></label></div><div class="field"><label>تاریخ و ساعت<input type="datetime-local" name="date" required value="${value}"></label></div><p>یادآور داخل این پیش‌نمونه با بازبودن صفحه بررسی می‌شود؛ اعلان بیرون برنامه نیازمند سرویس است.</p></form>`,`<button class="primary" type="submit" form="messenger-reminder">ذخیره یادآور</button>`);}
 function mediaPreview(p){u.pending=p;c.modal('بازبینی پیش از ارسال',`<form id="messenger-media">${p.attachments.map(attachment).join('')}<div class="field"><label>متن همراه<textarea name="text" placeholder="توضیح اختیاری"></textarea></label></div><p>${fa(p.attachments.length)} پیوست · آماده ثبت در همین گفتگو</p></form>`,`${action('cancel-media','لغو')}<button class="primary" type="submit" form="messenger-media">ارسال</button>`,true);}
 async function files(input){const contactId=c.contact();try{const attachments=[];for(const f of [...input.files]){const src=await c.fileData(f);if(!src)throw new Error('فایل خوانده نشد یا از اندازه مجاز بزرگ‌تر بود.');attachments.push({kind:f.type.startsWith('image/')?'image':f.type.startsWith('video/')?'video':f.type.startsWith('audio/')?'audio':'file',src,fileName:f.name});}if(attachments.length)mediaPreview({contactId,attachments});}catch(e){c.toast(e.message);}input.value='';}
 async function voice(){if(u.busy)return;if(u.recorder?.state==='recording'){u.recorder.stop();return;}if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){c.toast('ضبط در این مرورگر فعال نیست؛ فایل صوتی پیوست کنید.');return;}const contactId=c.contact();u.busy=true;u.cancelVoice=false;try{u.stream=await navigator.mediaDevices.getUserMedia({audio:true});const chunks=[];u.recorder=new MediaRecorder(u.stream);u.recorder.addEventListener('dataavailable',e=>{if(e.data.size)chunks.push(e.data);});u.recorder.addEventListener('stop',async()=>{const cancelled=u.cancelVoice;u.stream?.getTracks().forEach(t=>t.stop());const type=u.recorder?.mimeType||'audio/webm';u.recorder=null;u.stream=null;if(cancelled){c.render(true);return;}try{const src=await c.fileData(new Blob(chunks,{type}));if(src)mediaPreview({contactId,attachments:[{kind:'audio',src,fileName:'voice.webm'}]});}catch(e){c.toast(e.message);}c.render(true);});u.recorder.start();c.render(true);}catch{u.stream?.getTracks().forEach(t=>t.stop());c.toast('دسترسی میکروفن برقرار نشد.');}finally{u.busy=false;}}
 function cancel(){if(u.recorder?.state==='recording'){u.cancelVoice=true;u.recorder.stop();}u.pending=null;u.reply=null;u.selected=[];}
 const people=()=>Object.entries(roles).filter(([id,r])=>id!==c.actor()&&id!=='office'&&r.level===roles[c.actor()].level);
 function groupForm(x=null){c.modal(x?'مدیریت اعضای گروه':'گروه هم‌سطح جدید',`<form id="messenger-group" data-id="${x?.id||''}"><div class="field"><label>نام گروه<input name="name" required value="${esc(x?.name||'')}"></label></div><fieldset><legend>همکاران هم‌سطح</legend>${people().map(([id,r])=>`<label class="op-team-choice"><input type="checkbox" name="members" value="${id}" ${x?.members?.includes(id)?'checked':''}>${r.name}</label>`).join('')}</fieldset><p>سازنده مدیر این گروه است. عضویت گروه، دسترسی به تسک یا اطلاعات شخصی ایجاد نمی‌کند.</p></form>`,`<button class="primary" form="messenger-group" type="submit">ذخیره گروه</button>`);}
 function act(el){const a=el.dataset.msg,m=chosen(),x=current();if(!a)return false;
  if(a==='open'||a==='self'){u.selected=[];u.search='';c.nav('messages/'+(a==='self'?'self':el.dataset.contact));}
  else if(a==='back')c.nav('messages');
  else if(a==='active'||a==='archived'){u.filter=a;c.render(true);}
  else if(a==='new')c.modal('گفتگوی خصوصی',Object.entries(roles).filter(([id])=>id!==c.actor()).map(([id,r])=>action('start-direct',r.name,`data-id="${id}"`,'list-link')).join(''));
  else if(a==='start-direct'){const r=roles[el.dataset.id];if(!contacts().some(x=>x.id===el.dataset.id)){contacts().push({id:el.dataset.id,name:r.name,initial:r.name[0],role:r.title});threads()[el.dataset.id]=[];}c.save();c.nav('messages/'+el.dataset.id);}
  else if(a==='group')groupForm();
  else if(a==='info'){c.modal(x.name,`<p>${esc(x.role||'گفتگو')}</p>${x.group?(x.members||[]).map(id=>`<p>${esc(roles[id]?.name||id)}</p>`).join('')+(x.admin===c.actor()?action('group-edit','مدیریت اعضا'):''):''}`);}
  else if(a==='group-edit'&&x?.admin===c.actor())groupForm(x);
  else if(a==='chat-options')c.modal('تنظیمات گفتگو',[['pin-chat',x.pinned?'برداشتن سنجاق گفتگو':'سنجاق گفتگو'],['mute',x.muted?'فعال‌کردن صدا':'بی‌صدا'],['archive',x.archived?'خارج‌کردن از بایگانی':'بایگانی گفتگو']].map(([a,l])=>action(a,l,'','list-link')).join(''));
  else if(['pin-chat','mute','archive'].includes(a)){const key={ 'pin-chat':'pinned',mute:'muted',archive:'archived'}[a];x[key]=!x[key];c.closeModal();persist();}
  else if(a==='call')c.modal('تماس',`<p>تماس صوتی و تصویری در طرح پیام‌رسان منظور شده است. سرویس تماس متصل نیست.</p><button class="secondary" disabled>شروع تماس پس از اتصال سرویس</button>`);
  else if(a==='attach'||a==='camera')document.getElementById(a==='attach'?'messenger-file':'messenger-camera').click();
  else if(a==='voice')voice();
  else if(a==='cancel-recording')cancel();
  else if(a==='cancel-media'){u.pending=null;c.closeModal();}
  else if(a==='menu')menu(el.dataset.id);
  else if(a==='reply'){u.reply=structuredClone(m);c.closeModal();c.render(true);}
  else if(a==='cancel-reply'){u.reply=null;c.render(true);}
  else if(a==='forward')c.modal('بازارسال به گفتگو',contacts().map(x=>action('forward-to',x.name,`data-contact="${x.id}"`,'list-link')).join(''));
  else if(a==='forward-to'){const value=structuredClone(m);delete value.id;delete value.reminder;delete value.reminderState;delete value.reactions;add(el.dataset.contact,value.text,{...value,self:true,forwarded:true,id:uid('MSG')});c.closeModal();}
  else if(a==='react')c.modal('واکنش به پیام',['👍','❤️','✅','🙏','👀'].map(v=>action('reaction',v,`data-reaction="${v}"`)).join(''));
  else if(a==='reaction'){m.reactions||={};const r=m.reactions[el.dataset.reaction]||=[];if(r.includes(c.actor()))m.reactions[el.dataset.reaction]=r.filter(v=>v!==c.actor());else r.push(c.actor());c.closeModal();persist();}
  else if(a==='note'){add('self',m.text,{kind:m.kind,src:m.src,attachments:m.attachments,source:{contactId:u.chosen.contactId,messageIds:[m.id],label:contacts().find(x=>x.id===u.chosen.contactId)?.name}});c.closeModal();c.toast('در فضای خصوصی همین حساب ذخیره شد.');}
  else if(a==='select'){u.selected=u.selected.includes(m.id)?u.selected.filter(x=>x!==m.id):[...u.selected,m.id];c.closeModal();c.render(true);}
  else if(a==='clear-selection'){u.selected=[];c.render(true);}
  else if(a==='summary')c.modal('گزیده قابل ویرایش',`<form id="messenger-summary"><p>متن انتخاب‌شده منبع این نوت است؛ پردازش هوشمند متصل نیست. متن را پیش از ذخیره اصلاح کنید.</p><div class="field"><textarea name="text" aria-label="متن گزیده" required rows="9">${esc(sourceExcerpt(threads()[c.contact()],u.selected))}</textarea></div></form>`,`<button class="primary" form="messenger-summary" type="submit">ذخیره در نوت خصوصی</button>`);
  else if(a==='pin-message'){m.pinned=!m.pinned;c.closeModal();persist();}
  else if(a==='reminder')reminder();
  else if(a==='reminder-edit'||a==='reminder-snooze')reminder(m);
  else if(a==='reminder-done'||a==='reminder-cancel'){m.reminderState=a==='reminder-done'?'done':'cancelled';c.closeModal();persist();}
  else if(a==='edit')c.modal('ویرایش متن پیام',`<form id="messenger-edit"><div class="field"><textarea name="text" aria-label="متن پیام" required>${esc(m.text||'')}</textarea></div></form>`,`<button class="primary" form="messenger-edit" type="submit">ذخیره تغییر</button>`);
  else if(a==='delete'){removeMessage(m,c.actor(),c.archive(),u.chosen.contactId);c.closeModal();persist();}
  return true;
 }
 function submit(form){if(!form.id.startsWith('messenger-'))return false;const fd=new FormData(form);try{
  if(form.id==='messenger-form'){const text=String(fd.get('text')||'').trim();if(text)add(c.contact(),text);}
  else if(form.id==='messenger-media'){const p=u.pending;if(!p)throw new Error('پیوست آماده نیست.');add(p.contactId,String(fd.get('text')||''),p.attachments.length===1?p.attachments[0]:{kind:'album',attachments:p.attachments});u.pending=null;c.closeModal();}
  else if(form.id==='messenger-edit'){reviseMessage(chosen(),fd.get('text'),c.actor(),c.archive(),u.chosen.contactId);c.closeModal();persist();}
  else if(form.id==='messenger-group'){const id=form.dataset.id||uid('GROUP'),existing=contacts().find(x=>x.id===id);if(existing&&existing.admin!==c.actor())throw new Error('مدیریت این گروه در اختیار شما نیست.');const allowed=people().map(([id])=>id),members=fd.getAll('members').filter(id=>allowed.includes(id)),name=String(fd.get('name')||'').trim();if(!name)throw new Error('نام گروه لازم است.');const value={id,name,group:true,initial:name[0],role:'گروه هم‌سطح',admin:c.actor(),members:[c.actor(),...members]};if(existing)Object.assign(existing,value);else{contacts().push(value);threads()[id]=[];}c.closeModal();c.save();c.nav('messages/'+id);}
  else if(form.id==='messenger-summary'){const text=String(fd.get('text')||'').trim();if(!text)throw new Error('متن لازم است.');add('self',text,{source:{contactId:c.contact(),messageIds:[...u.selected],label:current()?.name}});u.selected=[];c.closeModal();}
  else if(form.id==='messenger-reminder'){const date=new Date(fd.get('date')),text=String(fd.get('text')||'').trim();if(!text||!Number.isFinite(+date))throw new Error('متن و تاریخ معتبر لازم است.');const old=threads().self.find(m=>m.id===form.dataset.edit);if(old){reviseMessage(old,text,c.actor(),c.archive(),'self');old.reminder=date.toISOString();old.reminderState='pending';delete old.notified;}else add('self',text,{reminder:date.toISOString(),reminderState:'pending',...(chosen()?{source:{contactId:u.chosen.contactId,messageIds:[chosen().id],label:contacts().find(x=>x.id===u.chosen.contactId)?.name}}:{})});c.closeModal();persist();}
 }catch(e){c.toast(e.message);}return true;}
 function input(el){if(el.id==='messenger-text')c.setDraft(c.contact(),el.value);if(el.id==='messenger-search'){u.search=el.value;document.getElementById('messenger-contacts').innerHTML=renderContacts();}}
 function change(el){if(['messenger-file','messenger-camera'].includes(el.id)){files(el);return true;}return false;}
 function tick(){let changed=false;for(const m of threads().self||[])if(m.reminder&&(!m.reminderState||m.reminderState==='pending')&&!m.notified&&new Date(m.reminder)<=new Date()){m.notified=true;c.notify({id:uid('REM'),kind:'reminder',ownerId:c.actor(),recipients:[c.actor()],name:'یادآور شخصی',text:' '+m.text,detail:'برای خودم',time:'اکنون',chat:'self',read:false});changed=true;}if(changed){c.save();c.render(true);}}
 return {render,act,submit,input,change,cancel,tick};
}
